-- Explicit original reserved goods used in actual dispatch; old unknown sources remain unknown.
CREATE TABLE inventory_reserved_batch_declarations(id TEXT PRIMARY KEY,outbound_id TEXT NOT NULL UNIQUE REFERENCES inventory_outbounds(id),store_id TEXT NOT NULL REFERENCES stores(id),sequence INTEGER NOT NULL CHECK(sequence>0),available_sequence INTEGER NOT NULL CHECK(available_sequence>=0),receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0),quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),source_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,sequence));
CREATE TABLE inventory_reserved_batch_refs(id TEXT PRIMARY KEY,declaration_id TEXT NOT NULL REFERENCES inventory_reserved_batch_declarations(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 30),custody_id TEXT NOT NULL REFERENCES inventory_reserved_roots(id),custody_version_id TEXT NOT NULL REFERENCES inventory_reserved_versions(id),custody_event_id TEXT NOT NULL REFERENCES inventory_reserved_events(id),receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),receipt_version_id TEXT NOT NULL REFERENCES purchase_receipt_versions(id),product_id TEXT NOT NULL REFERENCES retail_products(id),product_version INTEGER NOT NULL,unit TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),source_reference TEXT NOT NULL,note TEXT NOT NULL,UNIQUE(declaration_id,position),UNIQUE(declaration_id,custody_id),FOREIGN KEY(product_id,product_version) REFERENCES retail_product_versions(product_id,version));
CREATE TABLE inventory_custody_reserved_sales_context(version_id TEXT PRIMARY KEY REFERENCES inventory_custody_versions(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO inventory_custody_reserved_sales_context SELECT id,0 FROM inventory_custody_versions;
CREATE TRIGGER inventory_custody_reserved_sales_context_capture AFTER INSERT ON inventory_custody_versions BEGIN INSERT INTO inventory_custody_reserved_sales_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_reserved_sales_context_source BEFORE INSERT ON inventory_custody_reserved_sales_context WHEN NOT EXISTS(SELECT 1 FROM inventory_custody_versions x WHERE x.id=NEW.version_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_custody_reserved_sales_context_time BEFORE INSERT ON inventory_custody_versions WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE inventory_reserved_reserved_sales_context(version_id TEXT PRIMARY KEY REFERENCES inventory_reserved_versions(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO inventory_reserved_reserved_sales_context SELECT id,0 FROM inventory_reserved_versions;
CREATE TRIGGER inventory_reserved_reserved_sales_context_capture AFTER INSERT ON inventory_reserved_versions BEGIN INSERT INTO inventory_reserved_reserved_sales_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_reserved_sales_context_source BEFORE INSERT ON inventory_reserved_reserved_sales_context WHEN NOT EXISTS(SELECT 1 FROM inventory_reserved_versions x WHERE x.id=NEW.version_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_reserved_reserved_sales_context_time BEFORE INSERT ON inventory_reserved_versions WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE purchase_quality_reserved_sales_context(case_id TEXT PRIMARY KEY REFERENCES purchase_quality_cases(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO purchase_quality_reserved_sales_context SELECT id,0 FROM purchase_quality_cases;
CREATE TRIGGER purchase_quality_reserved_sales_context_capture AFTER INSERT ON purchase_quality_cases BEGIN INSERT INTO purchase_quality_reserved_sales_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER purchase_quality_reserved_sales_context_source BEFORE INSERT ON purchase_quality_reserved_sales_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_cases x WHERE x.id=NEW.case_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER purchase_quality_reserved_sales_context_time BEFORE INSERT ON purchase_quality_cases WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE inventory_available_reserved_sales_context(declaration_id TEXT PRIMARY KEY REFERENCES inventory_batch_declarations(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO inventory_available_reserved_sales_context SELECT id,0 FROM inventory_batch_declarations;
CREATE TRIGGER inventory_available_reserved_sales_context_capture AFTER INSERT ON inventory_batch_declarations BEGIN INSERT INTO inventory_available_reserved_sales_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_available_reserved_sales_context_source BEFORE INSERT ON inventory_available_reserved_sales_context WHEN NOT EXISTS(SELECT 1 FROM inventory_batch_declarations x WHERE x.id=NEW.declaration_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_available_reserved_sales_context_time BEFORE INSERT ON inventory_batch_declarations WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE inventory_reserved_sales_receipt_context(receipt_event_id TEXT PRIMARY KEY REFERENCES purchase_receipt_events(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO inventory_reserved_sales_receipt_context SELECT id,0 FROM purchase_receipt_events;
CREATE TRIGGER inventory_reserved_sales_receipt_context_capture AFTER INSERT ON purchase_receipt_events BEGIN INSERT INTO inventory_reserved_sales_receipt_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_sales_receipt_context_source BEFORE INSERT ON inventory_reserved_sales_receipt_context WHEN NOT EXISTS(SELECT 1 FROM purchase_receipt_events x WHERE x.id=NEW.receipt_event_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_reserved_sales_receipt_context_time BEFORE INSERT ON purchase_receipt_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE inventory_reserved_sales_quality_context(quality_event_id TEXT PRIMARY KEY REFERENCES purchase_quality_events(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0));
INSERT INTO inventory_reserved_sales_quality_context SELECT id,0 FROM purchase_quality_events;
CREATE TRIGGER inventory_reserved_sales_quality_context_capture AFTER INSERT ON purchase_quality_events BEGIN INSERT INTO inventory_reserved_sales_quality_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_sales_quality_context_source BEFORE INSERT ON inventory_reserved_sales_quality_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events x WHERE x.id=NEW.quality_event_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_reserved_sales_quality_context_time BEFORE INSERT ON purchase_quality_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TABLE inventory_reserved_sales_dispatch_context(outbound_id TEXT PRIMARY KEY REFERENCES inventory_outbounds(id),reserved_sequence INTEGER NOT NULL CHECK(reserved_sequence>=0),legacy INTEGER NOT NULL CHECK(legacy IN(0,1)));
INSERT INTO inventory_reserved_sales_dispatch_context SELECT id,0,1 FROM inventory_outbounds;
CREATE TRIGGER inventory_reserved_sales_dispatch_context_capture AFTER INSERT ON inventory_outbounds BEGIN INSERT INTO inventory_reserved_sales_dispatch_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),0),0);END;
CREATE TRIGGER inventory_reserved_sales_dispatch_context_source BEFORE INSERT ON inventory_reserved_sales_dispatch_context WHEN NOT EXISTS(SELECT 1 FROM inventory_outbounds x WHERE x.id=NEW.outbound_id AND NEW.reserved_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_batch_declarations WHERE store_id=x.store_id),0) AND NEW.legacy=0) BEGIN SELECT RAISE(ABORT,'reserved batch original context');END;
CREATE TRIGGER inventory_reserved_sales_dispatch_context_time BEFORE INSERT ON inventory_outbounds WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch source chronology');END;
CREATE TRIGGER inventory_custody_versions_reserved_sales_capacity BEFORE INSERT ON inventory_custody_versions WHEN EXISTS(SELECT 1 FROM inventory_custody_roots c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND NEW.quantity>r.bound_quantity-(coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE receipt_id=r.id),0))-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-CASE WHEN NEW.bucket='available' THEN coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'batch known sold original capacity');END;
CREATE TRIGGER inventory_reserved_versions_reserved_sales_capacity BEFORE INSERT ON inventory_reserved_versions WHEN EXISTS(SELECT 1 FROM inventory_reserved_roots c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND NEW.quantity>r.bound_quantity-(coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE receipt_id=r.id),0))-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) BEGIN SELECT RAISE(ABORT,'batch known sold original capacity');END;
CREATE TRIGGER purchase_quality_cases_reserved_sales_capacity BEFORE INSERT ON purchase_quality_cases WHEN EXISTS(SELECT 1 FROM purchase_receipts r WHERE r.id=NEW.receipt_id AND NEW.quantity>r.bound_quantity-(coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE receipt_id=r.id),0))-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) BEGIN SELECT RAISE(ABORT,'batch known sold original capacity');END;
CREATE TRIGGER inventory_available_reserved_sales_capacity BEFORE INSERT ON inventory_batch_refs WHEN EXISTS(SELECT 1 FROM purchase_receipts r WHERE r.id=NEW.receipt_id AND NEW.quantity>r.bound_quantity-(coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE receipt_id=r.id),0))-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) BEGIN SELECT RAISE(ABORT,'batch original total capacity');END;
CREATE TRIGGER inventory_reserved_batch_declaration_source BEFORE INSERT ON inventory_reserved_batch_declarations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_outbounds e JOIN inventory_reserved_sales_dispatch_context x ON x.outbound_id=e.id WHERE e.id=NEW.outbound_id AND x.legacy=0 AND x.reserved_sequence+1=NEW.sequence AND e.store_id=NEW.store_id AND e.source_mode='reserved' AND e.quantity=NEW.quantity AND e.outbound_revision=(SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=e.product_id) AND e.created_at=NEW.created_at AND e.created_by=NEW.created_by) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 THEN RAISE(ABORT,'reserved batch actual outbound/actor/sequence') END;
 SELECT CASE WHEN NEW.available_sequence<>coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) THEN RAISE(ABORT,'reserved batch original prefix/time') END;
END;
CREATE TRIGGER inventory_reserved_batch_ref_source BEFORE INSERT ON inventory_reserved_batch_refs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations d JOIN inventory_outbounds e ON e.id=d.outbound_id JOIN inventory_reserved_roots c ON c.id=NEW.custody_id JOIN inventory_reserved_versions v ON v.id=NEW.custody_version_id AND v.root_id=c.id JOIN inventory_reserved_current ce ON ce.root_id=c.id JOIN inventory_reserved_dispatch_context dc ON dc.outbound_id=e.id JOIN inventory_order_events oe ON oe.id=c.reservation_id JOIN inventory_order_lines ol ON ol.event_id=oe.id AND ol.position=c.order_position JOIN purchase_receipts r ON r.id=c.receipt_id JOIN purchase_receipt_current rc ON rc.receipt_id=r.id JOIN retail_product_versions pv ON pv.product_id=r.product_id AND pv.version=r.product_version JOIN retail_product_versions ev ON ev.product_id=e.product_id AND ev.version=e.product_version JOIN inventory_dispatch_return_context rt ON rt.outbound_id=e.id JOIN inventory_reserved_reserved_sales_context vc ON vc.version_id=v.id WHERE d.id=NEW.declaration_id AND e.reservation_id=c.reservation_id AND e.position=c.order_position AND oe.revision=(SELECT max(revision) FROM inventory_order_events WHERE order_id=oe.order_id) AND v.reservation_revision=oe.revision AND oe.order_id=e.order_id AND r.id=NEW.receipt_id AND r.product_id=NEW.product_id AND r.product_version=NEW.product_version AND pv.unit=NEW.unit AND pv.unit=ev.unit AND pv.category=ev.category AND e.product_id=r.product_id AND e.store_id=r.store_id AND c.store_id=e.store_id AND rc.status='posted' AND rc.version_id=v.receipt_version_id AND NEW.receipt_version_id=v.receipt_version_id AND ce.status='recorded' AND ce.action='observe' AND ce.id=NEW.custody_event_id AND ce.version_id=v.id AND ce.sequence<=dc.custody_sequence AND v.bucket='reserved' AND v.stock_sequence=e.basis_sequence AND v.outbound_revision+1=e.outbound_revision AND v.product_return_revision=rt.product_return_revision AND v.quality_sequence=d.quality_sequence AND v.batch_sequence=d.available_sequence AND coalesce((SELECT sum(b.quantity) FROM inventory_reserved_batch_refs b JOIN inventory_reserved_batch_declarations bd ON bd.id=b.declaration_id WHERE b.receipt_id=r.id AND bd.sequence<=vc.reserved_sequence),0)=coalesce((SELECT sum(b.quantity) FROM inventory_reserved_batch_refs b WHERE b.receipt_id=r.id AND b.declaration_id<>d.id),0) AND v.created_at<=e.created_at AND NEW.quantity<=v.quantity-coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE custody_version_id=v.id),0) AND NEW.quantity<=r.bound_quantity-(coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE receipt_id=r.id),0))-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) OR NEW.position<>coalesce((SELECT max(position)+1 FROM inventory_reserved_batch_refs WHERE declaration_id=NEW.declaration_id),1) OR NEW.quantity+coalesce((SELECT sum(quantity) FROM inventory_reserved_batch_refs WHERE declaration_id=NEW.declaration_id),0)>(SELECT quantity FROM inventory_reserved_batch_declarations WHERE id=NEW.declaration_id) OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 THEN RAISE(ABORT,'reserved batch fixed original observation/unit/quantity/source') END;
END;
CREATE TRIGGER inventory_custody_events_reserved_sales_time BEFORE INSERT ON inventory_custody_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved batch observation chronology');END;
