CREATE TRIGGER inventory_reserved_sales_receipt_context_no_update BEFORE UPDATE ON inventory_reserved_sales_receipt_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_reserved_sales_receipt_context_no_delete BEFORE DELETE ON inventory_reserved_sales_receipt_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_reserved_sales_quality_context_no_update BEFORE UPDATE ON inventory_reserved_sales_quality_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_reserved_sales_quality_context_no_delete BEFORE DELETE ON inventory_reserved_sales_quality_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_reserved_sales_dispatch_context_no_update BEFORE UPDATE ON inventory_reserved_sales_dispatch_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_reserved_sales_dispatch_context_no_delete BEFORE DELETE ON inventory_reserved_sales_dispatch_context BEGIN SELECT RAISE(ABORT,'reserved batch immutable');END;
CREATE TRIGGER inventory_available_reserved_sales_source BEFORE INSERT ON inventory_batch_refs WHEN NOT EXISTS(SELECT 1 FROM inventory_custody_reserved_sales_context c JOIN inventory_available_reserved_sales_context d ON d.declaration_id=NEW.declaration_id WHERE c.version_id=NEW.custody_version_id AND coalesce((SELECT sum(b.quantity) FROM inventory_reserved_batch_refs b JOIN inventory_reserved_batch_declarations bd ON bd.id=b.declaration_id WHERE b.receipt_id=NEW.receipt_id AND bd.sequence<=c.reserved_sequence),0)=coalesce((SELECT sum(b.quantity) FROM inventory_reserved_batch_refs b JOIN inventory_reserved_batch_declarations bd ON bd.id=b.declaration_id WHERE b.receipt_id=NEW.receipt_id AND bd.sequence<=d.reserved_sequence),0)) BEGIN SELECT RAISE(ABORT,'batch original reserved sales source prefix');END;
